import{_ as a,o as d,c as l,ag as o}from"./chunks/framework.IxO3mcwW.js";const q=JSON.parse('{"title":"分享和团队管理","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge-base/team.md","filePath":"knowledge-base/team.md","lastUpdated":1773147350000}'),i={name:"knowledge-base/team.md"};function e(r,t,p,h,u,s){return d(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="分享和团队管理" tabindex="-1">分享和团队管理 <a class="header-anchor" href="#分享和团队管理" aria-label="Permalink to &quot;分享和团队管理&quot;">​</a></h1><blockquote><p>📤 分享订阅，知识触手可及</p></blockquote><p>支持将知识库以多种形式（微信小程序、分享海报、链接等）分享给他人，也可订阅其他人的「靠谱知识库」，获取独家内容和实时更新。共享智慧，扩展视野，让学习更高效！</p><p>同时，新增了知识库的团队管理功能，可以让知识库在限定范围内进行共创和使用，大大提高了知识库的共创和灵活性。</p><h2 id="app端使用说明" tabindex="-1">APP端使用说明 <a class="header-anchor" href="#app端使用说明" aria-label="Permalink to &quot;APP端使用说明&quot;">​</a></h2><p>个人自己创建的知识库，默认是私密状态，仅自己可见。</p><p>如果想要分享给他人查看，或邀请团队成员共同使用，需要手动设置知识库的分享权限。</p><p><strong>权限包括：</strong></p><ul><li><strong>公开</strong>：获得你的知识库分享链接或分享海报的人，都可以访问知识库使用（AI搜索、查看内容）</li><li><strong>团队</strong>：获得你的知识库分享链接或分享海报的人，无法直接访问知识库内容，需要先申请加入才能使用</li></ul><div class="tip custom-block"><p class="custom-block-title">团队权限说明</p><p>创建人可以自定义成员加入时，是否需要管理员审核通过后才能加入</p></div><h2 id="分享自己的知识库" tabindex="-1">分享自己的知识库 <a class="header-anchor" href="#分享自己的知识库" aria-label="Permalink to &quot;分享自己的知识库&quot;">​</a></h2><ol><li><p>在知识库内，点击右上角分享按钮</p></li><li><p>选择&quot;公开&quot;，然后将知识库通过「微信好友」、「朋友圈」、「分享海报」和「分享链接」等形式分享出去</p></li><li><p>他人在访问你的知识库时，可以直接进入知识库来使用</p></li></ol><h2 id="订阅他人公开的知识库" tabindex="-1">订阅他人公开的知识库 <a class="header-anchor" href="#订阅他人公开的知识库" aria-label="Permalink to &quot;订阅他人公开的知识库&quot;">​</a></h2><ol><li><p>点击他人分享给你的知识库小程序、海报或链接</p></li><li><p>点击进入知识库页面，可以点击&quot;+订阅&quot;，订阅后的知识库，会出现在「我的」知识库列表内</p></li><li><p>同时，你也可以在精选 tab 下，点开官方精选知识库，并点击&quot;订阅&quot;按钮，完成订阅</p></li><li><p>如果想取消已订阅的知识库，可以再次点击即可&quot;取消订阅&quot;</p></li></ol><h2 id="设置团队知识库" tabindex="-1">设置团队知识库 <a class="header-anchor" href="#设置团队知识库" aria-label="Permalink to &quot;设置团队知识库&quot;">​</a></h2><ol><li><p>在知识库内，点击右上角分享按钮</p></li><li><p>选择&quot;团队可见&quot;，然后将知识库通过「微信好友」、「朋友圈」、「分享海报」和「分享链接」等形式分享出去</p></li></ol><div class="warning custom-block"><p class="custom-block-title">审核设置</p><p>默认&quot;成员自动加入&quot;是关闭的，即加入的成员需要管理员审核通过才能访问知识库。其他成员点击进入知识库页面，可以点击&quot;申请加入知识库&quot;，然后等待知识库管理员的审核即可。</p></div><ol start="3"><li><p>管理员审核同意后，加入后的知识库，会出现在其他成员「我的」知识库列表内</p></li><li><p>如果打开&quot;成员自动加入&quot;，则不需要任何审核确认，成员可以直接加入并使用知识库</p></li></ol><h3 id="审核加入团队知识库申请" tabindex="-1">审核加入团队知识库申请 <a class="header-anchor" href="#审核加入团队知识库申请" aria-label="Permalink to &quot;审核加入团队知识库申请&quot;">​</a></h3><ol><li><p>有新的成员申请加入时，知识库顶部成员入口会有红点提醒，点击&quot;成员&quot;入口进入成员管理页面</p></li><li><p>可以对申请的成员进行审核，可以同意加入，也可以拒绝，同意加入则进入成员列表，可以分配具体角色权限</p></li><li><p>可以将其设置为普通成员和管理员，具体请参考下面的【角色权限说明】表格</p></li><li><p>同时，可以将已加入的成员，从知识库移除，则其无法再正常访问和使用知识库</p></li></ol><h3 id="团队角色和权限说明" tabindex="-1">团队角色和权限说明 <a class="header-anchor" href="#团队角色和权限说明" aria-label="Permalink to &quot;团队角色和权限说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>权限</th><th>成员</th><th>管理员</th><th>创建人</th></tr></thead><tbody><tr><td><strong>知识库管理</strong></td><td></td><td></td><td></td></tr><tr><td>编辑名称和描述</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>删除知识库</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>修改分享权限</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>审批成员</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td><strong>内容管理</strong></td><td></td><td></td><td></td></tr><tr><td>添加内容</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>编辑内容</td><td>仅自己</td><td>仅自己</td><td>仅自己</td></tr><tr><td>删除内容</td><td>仅自己</td><td>仅自己</td><td>仅自己</td></tr><tr><td>移出内容</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>订阅直播/博主</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>查看、分享、复制</td><td>✅</td><td>✅</td><td>✅</td></tr></tbody></table><h2 id="网页端使用说明" tabindex="-1">网页端使用说明 <a class="header-anchor" href="#网页端使用说明" aria-label="Permalink to &quot;网页端使用说明&quot;">​</a></h2><h3 id="分享自己的知识库-1" tabindex="-1">分享自己的知识库 <a class="header-anchor" href="#分享自己的知识库-1" aria-label="Permalink to &quot;分享自己的知识库&quot;">​</a></h3><ol><li><p>进入知识库内，点击右上角&quot;分享&quot;按钮，选择&quot;公开&quot;后，然后复制链接给他人，即可实现分享</p></li><li><p>如果不想其他人能访问到此知识库，则关闭此开关，则他人无法继续访问和使用你的知识库</p></li><li><p>如果想要团队共同维护一个知识库，则选择&quot;团队&quot;，即可由团队管理员共同维护此知识库</p></li></ol><h3 id="订阅他人的知识库" tabindex="-1">订阅他人的知识库 <a class="header-anchor" href="#订阅他人的知识库" aria-label="Permalink to &quot;订阅他人的知识库&quot;">​</a></h3><ol><li><p>打开别人分享给你的知识库，点击右上角&quot;订阅知识库&quot;</p></li><li><p>订阅成功后，该知识库会出现在你的知识库列表内</p></li><li><p>如果想取消已订阅的知识库，可以点击他人知识库的 ... 更多入口，选择&quot;取消订阅&quot;</p></li></ol><h2 id="小程序端使用说明" tabindex="-1">小程序端使用说明 <a class="header-anchor" href="#小程序端使用说明" aria-label="Permalink to &quot;小程序端使用说明&quot;">​</a></h2><ol><li><p>进入 Get 笔记小程序，点击右上角更多，可以进入知识库列表页</p></li><li><p>选择要访问的知识库，然后在知识库内，点击右上角分享按钮</p></li><li><p>选择&quot;公开&quot;，可以将知识库通过「微信好友」、「朋友圈」、「分享海报」和「分享链接」等形式分享出去</p><p>则他人在访问你的知识库时，可以直接进入知识库来订阅、使用</p></li><li><p>如果想要团队共同维护一个知识库，则选择&quot;团队&quot;，即可由团队管理员共同维护此知识库</p></li></ol>',29)])])}const c=a(i,[["render",e]]);export{q as __pageData,c as default};
